def raw_exercise():
    L = ['مشق', '']
    L += [f'{n}۔ {q}' for n, (q, _) in zip(['۱', '۲', '۳', '۴', '۵', '۶'], QS[:6])]
    L += ['۷۔ جملے درست کریں۔', '(i) وہ آبِ زمزم کا پانی لایا ہے۔', '(ii) پاکستان دن بدن ترقی کر رہا ہے۔', '(iii) میں نے لاہور جانا ہے۔',
          '(iv) ہمارا قومی زبان اردو ہے۔', '(v) خوشحال خان خٹک پشتو زبان کی شاعر تھا۔']
    L += ['۸۔ مندرجہ ذیل الفاظ میں سے مذکر، مؤنث الگ کریں۔', 'کمبل، مطالعہ، پردہ، دستک، جنبش، رسالہ، شکایت، بیگ، ناغہ، بارش۔', '', TEACHER]
    return '\n'.join(L)


def fix_exercise(ex):
    ex['rawExercise'] = raw_exercise()
    ex['blanks'] = []
    ex['shortQuestions'] = [dict(question=q, answer=a) for q, a in QS]
    ex['vocabulary'] = [dict(word=w, meaning=m, sentence=s) for w, m, s in VOCAB]
    ex['grammar'] = GRAMMAR
    ex['teacherInstructions'] = [TEACHER.split(': ', 1)[1]]
    ex['answerNote'] = 'SpaceBook answers (the textbook prints no answers).'


